"""Local helper: normalize the auth_part fragments collected from the shared
folder and print them in service order. Kept outside /shared on purpose."""
import os, re

SHARED = "/shared"

# Fragment files seen in the shared folder, with the owning assistant.
CANDIDATE_FILES = {
    "ava": ["deploy_token_parts/ava.part"],
    "ben": ["deploy_token_parts/ben.part", "deploy_token/ben.part"],
    "eli": ["deploy_token_parts/eli.part"],
    "jun": ["deploy_token_parts/jun.part", "auth_parts/jun.txt"],
}

# Service order derived from the v2 service names of the four migrated configs.
SERVICE_OF = {
    "eli": "payments-gateway",
    "ben": "payments-ledger",
    "ava": "payments-notifier",
    "jun": "payments-scheduler",
}

LABEL = re.compile(r"^(?:[a-z]+)\s*:\s*(.*)$")


def normalize(path):
    """Return the bare fragment string from a part file, or None."""
    try:
        with open(path) as fh:
            raw = fh.read()
    except OSError:
        return None
    for line in raw.splitlines():
        line = line.strip()
        if not line:
            continue
        m = LABEL.match(line)
        if m:
            line = m.group(1).strip()
        if line:
            return line
    return None


for who in ("eli", "ben", "ava", "jun"):
    seen = []
    for rel in CANDIDATE_FILES[who]:
        frag = normalize(os.path.join(SHARED, rel))
        if frag:
            seen.append((rel, frag))
    uniq = {f for _, f in seen}
    status = "OK " if len(uniq) == 1 else "CHECK"
    print(f"{status} {who:4s} {SERVICE_OF[who]:20s} {seen}")
"}

